<?php
require_once __DIR__.'/../../config/cors.php'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../helpers/response.php'; require_once __DIR__.'/../../middleware/auth.php';
$actor=requireAuth($pdo);$method=$_SERVER['REQUEST_METHOD'];if($method!=='GET')requireCsrfToken();
if($method==='GET'){ $where=[];$p=[];if(isset($_GET['id'])){$where[]='v.id=:id';$p['id']=(int)$_GET['id'];}if(isset($_GET['status'])&&$_GET['status']!==''){$where[]='v.status=:status';$p['status']=$_GET['status'];}$q=trim((string)($_GET['search']??''));if($q!==''){$where[]='(v.registration_number LIKE :q OR v.vehicle_type LIKE :q OR v.make_model LIKE :q OR d.name LIKE :q)';$p['q']='%'.$q.'%';}$sql="SELECT v.id,v.registration_number AS registrationNumber,v.vehicle_type AS vehicleType,v.make_model AS makeModel,v.capacity,v.status,v.driver_id AS driverId,COALESCE(d.name, '') AS driverName FROM vehicles v LEFT JOIN drivers d ON d.id=v.driver_id";if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY v.registration_number';$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();foreach($rows as &$r){$r['id']=(string)$r['id'];if($r['driverId']!==null)$r['driverId']=(string)$r['driverId'];$r['capacity']=(int)$r['capacity'];}sendResponse(['success'=>true,'data'=>isset($_GET['id'])?($rows[0]??null):$rows]);}
if($actor['role']!=='admin')sendError('Admin access required.',403);$body=json_decode(file_get_contents('php://input'),true)?:[];$id=isset($_GET['id'])?(int)$_GET['id']:0;$reg=trim((string)($body['registrationNumber']??''));$type=trim((string)($body['vehicleType']??''));$make=trim((string)($body['makeModel']??''));$capacity=max(1,(int)($body['capacity']??1));$status=$body['status']??'active';$driverId=isset($body['driverId'])&&$body['driverId']!==''?(int)$body['driverId']:null;if($reg===''||$type==='')sendError('registrationNumber and vehicleType are required.',422);if(!in_array($status,['active','inactive','maintenance'],true))sendError('Invalid vehicle status.',422);if($driverId){$x=$pdo->prepare("SELECT id FROM drivers WHERE id=:id AND status='active'");$x->execute(['id'=>$driverId]);if(!$x->fetchColumn())sendError('Driver not found or inactive.',422);}if($method==='POST'){$st=$pdo->prepare('INSERT INTO vehicles(registration_number,vehicle_type,make_model,capacity,status,driver_id) VALUES(:reg,:type,:make,:capacity,:status,:driver)');$st->execute(['reg'=>$reg,'type'=>$type,'make'=>$make,'capacity'=>$capacity,'status'=>$status,'driver'=>$driverId]);$id=(int)$pdo->lastInsertId();}elseif(in_array($method,['PUT','PATCH'],true)&&$id){$st=$pdo->prepare('UPDATE vehicles SET registration_number=:reg,vehicle_type=:type,make_model=:make,capacity=:capacity,status=:status,driver_id=:driver WHERE id=:id');$st->execute(['reg'=>$reg,'type'=>$type,'make'=>$make,'capacity'=>$capacity,'status'=>$status,'driver'=>$driverId,'id'=>$id]);}else sendError('Invalid vehicle request.',400);$st=$pdo->prepare('SELECT id,registration_number AS registrationNumber,vehicle_type AS vehicleType,make_model AS makeModel,capacity,status,driver_id AS driverId FROM vehicles WHERE id=:id');$st->execute(['id'=>$id]);sendResponse(['success'=>true,'data'=>$st->fetch()],$method==='POST'?201:200);
